export type JournalSelection={journalId:string;version:string;stage:'initial'|'revision'|'production';purpose:'main'|'supplementary'|'graphical_abstract'|'toc'|'cover';contentType:'schematic'|'data'|'primary'|'illustration';contentSource?:'figure-type';figureTypeId?:string;widthMm:number;rasterKind:'color'|'grayscale'|'lineart'};
