export type JournalSnapshot={id:string;name:string;publisher:string;status:string;summary:string;subjects?:string[];version:string;verifiedOn:string;defaults:{widthMm:number};sourceIds:string[];sources:JournalSource[];inheritance:{sourceId:string;scope:string;status:string}[];rules:JournalRule[];selection:JournalSelection;snapshotSchema:1};
